using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Modules.Maquinaria.DTOs;using TransPort.Api.Modules.Maquinaria.Repositories;
namespace TransPort.Api.Controllers;
[ApiController,Route("api/maquinarias"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo")]
public sealed class MaquinariasController(IMaquinariaRepository repo):ControllerBase
{
 [HttpGet]public Task<IReadOnlyList<MaquinariaEquipoDto>>Listar(string?estado,int?sedeId,string?busqueda,CancellationToken ct)=>repo.ListarAsync(estado,sedeId,busqueda,A(),ct);[HttpGet("opciones")]public Task<MaquinariaOpcionesDto>Opciones(CancellationToken ct)=>repo.OpcionesAsync(A(),ct);[HttpGet("{id:int}")]public async Task<IActionResult>Obtener(int id,CancellationToken ct){var x=await repo.ObtenerAsync(id,A(),ct);return x is null?NotFound():Ok(x);}[HttpPost]public async Task<IActionResult>Crear(CrearMaquinariaRequest x,CancellationToken ct)=>Ok(new ResultadoMaquinariaDto(await repo.CrearEquipoAsync(x,A(),ct)));[HttpPost("contratos")]public async Task<IActionResult>Contrato(CrearContratoMaquinariaRequest x,CancellationToken ct)=>Ok(new ResultadoMaquinariaDto(await repo.CrearContratoAsync(x,A(),ct)));[HttpPut("contratos/{id:long}/estado")]public async Task<IActionResult>EstadoContrato(long id,EstadoContratoMaquinariaRequest x,CancellationToken ct)=>await repo.EstadoContratoAsync(id,x,A(),ct)?NoContent():NotFound();[HttpPost("mantenimientos")]public async Task<IActionResult>Mantenimiento(CrearMantenimientoMaquinariaRequest x,CancellationToken ct)=>Ok(new ResultadoMaquinariaDto(await repo.CrearMantenimientoAsync(x,A(),ct)));[HttpPut("mantenimientos/{id:long}/estado")]public async Task<IActionResult>EstadoMantenimiento(long id,EstadoMantenimientoMaquinariaRequest x,CancellationToken ct)=>await repo.EstadoMantenimientoAsync(id,x,A(),ct)?NoContent():NotFound();[HttpDelete("{id:int}"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(int id,CancellationToken ct)=>await repo.EliminarEquipoAsync(id,A().UsuarioId,ct)?NoContent():NotFound();private AlcanceMaquinaria A()=>new(int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!),User.IsInRole("AdministradorGeneral"));
}
